import{z as l,x as A,o as t,c as B,q as n,j as s,D as o,d as e,s as d,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"管程与条件变量","description":"","frontmatter":{"title":"管程与条件变量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/monitor-condvar.md","filePath":"cs/monitor-condvar.md","lastUpdated":1791413859000}'),c={name:"cs/monitor-condvar.md"};function p(D,a,m,u,h,C){const r=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=n('<h1 id="管程与条件变量" tabindex="-1">管程与条件变量 <a class="header-anchor" href="#管程与条件变量" aria-label="Permalink to &quot;管程与条件变量&quot;">​</a></h1><div class="epigraph"><p>管程把共享数据与操作它的过程包在一起；过程在管程内互斥执行，条件变量用于等待不变量重新成立。</p><footer>—— 据 Hoare, Monitors: An Operating System Structuring Concept, CACM 1974 整理</footer></div><p><a href="/cs/semaphore">上一课</a>能计数等待，但 P/V 散落在各处，编译器看不见「哪把锁护哪块数据」。缺口是语言级模块：进入即持锁，退出即放锁，等待改写成条件变量。本课钉管程与 <code>wait</code>/<code>signal</code>，不把死锁图谱画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用三个信号量实现有界缓冲，容易 V 错对象。管程约定：模块内任意时刻至多一个活动过程（互斥自动）。当不变量暂时不成立（缓冲空），过程在条件变量上等待——等待必须<strong>释放管程锁</strong>，否则无人能生产。缺口是这套括号，不是新的硬件原子。</p><p>Hoare 语义：<code>signal</code> 立即切到等待者，信号方暂停。Mesa/Java 语义：<code>signal</code> 只唤醒，被唤醒者回头再检查条件。主干标明差别，实现课默认 Mesa：等待必须写成循环。</p><p><span class="marginnote">条件变量本身不记布尔值。布尔在管程的普通变量里；条件变量只是等待队列的名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进入管程 = 获得隐含互斥。<code>wait(c)</code>：释放互斥，挂到 \\(c\\)，被唤醒后重新获得互斥。<code>signal(c)</code> / <code>broadcast(c)</code>：唤醒一个或全部。有界缓冲的 <code>put</code>/<code>get</code> 都在管程内，空与满各用一个条件变量。</p><p><span class="marginnote">拿容量 \\(N=4\\) 的有界缓冲代入：队列里已有 4 个元素时 <code>put</code> 走 <code>wait(notFull)</code>——空位数是 0；消费者取走一个后 <code>signal(notFull)</code>，生产者醒来看到空位数为 1，写入成功。空与满各配一个条件变量，谁在等什么一目了然。</span></p>',10)),(t(),s(i,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENTER%5B%22%E8%BF%9B%E5%85%A5%3A%20%E6%8C%81%E7%AE%A1%E7%A8%8B%E9%94%81%22%5D%20--%3E%20CHECK%5B%22%E6%A3%80%E6%9F%A5%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20CHECK%20--%3E%20WAIT%5B%22wait%3A%20%E6%94%BE%E9%94%81%E5%B9%B6%E7%9D%A1%22%5D%0A%20%20WAIT%20--%3E%20RE%5B%22%E5%94%A4%E9%86%92%E5%90%8E%E9%87%8D%E6%96%B0%E6%8C%81%E9%94%81%22%5D%0A%20%20CHECK%20--%3E%20BODY%5B%22%E4%BF%AE%E6%94%B9%E5%85%B1%E4%BA%AB%E6%95%B0%E6%8D%AE%22%5D%0A%20%20BODY%20--%3E%20SIG%5B%22signal%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("管程把"),E("a",{href:"/cs/race-critical"},"临界区"),e("变成类型边界：模块外碰不到裸计数。条件等待把「互斥」与「等某谓词」拆开，避免用信号量兼做两职时的协议错误。内核里的等待队列加睡眠锁，是管程的手写版；POSIX "),E("code",null,"pthread_cond"),e(" 是用户版。")],-1)),a[5]||(a[5]=E("p",null,"与信号量相比，谁该被唤醒由条件变量指名，而不是「任意 V」。广播可能惊群，这是性能边界，不是语义必须。",-1)),(t(),s(i,null,{default:o(()=>[d(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22signal(c)%20%E8%A2%AB%E8%B0%83%E7%94%A8%22%5D%20--%3E%20Q%7B%22%E5%93%AA%E7%A7%8D%E8%AF%AD%E4%B9%89%3F%22%7D%0A%20%20Q%20--%3E%7C%22Hoare%201974%22%7C%20H1%5B%22%E4%BF%A1%E5%8F%B7%E6%96%B9%E7%AB%8B%E5%8D%B3%E6%9A%82%E5%81%9C%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E7%AD%89%E5%BE%85%E8%80%85%E5%BD%93%E5%9C%BA%E8%BF%90%E8%A1%8C%22%5D%0A%20%20H2%20--%3E%20H3%5B%22%E7%AD%89%E5%BE%85%E8%80%85%E9%80%80%E5%87%BA%E6%88%96%E5%86%8D%20wait%20%E6%97%B6%22%5D%0A%20%20H3%20--%3E%20H4%5B%22%E4%BF%A1%E5%8F%B7%E6%96%B9%E6%89%8D%E6%81%A2%E5%A4%8D%22%5D%0A%20%20Q%20--%3E%7C%22Mesa%20%2F%20Java%22%7C%20M1%5B%22%E4%BF%A1%E5%8F%B7%E6%96%B9%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E7%AD%89%E5%BE%85%E8%80%85%E6%8E%92%E9%98%9F%E6%8A%A2%E9%94%81%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E6%8A%A2%E5%88%B0%E9%94%81%E5%90%8E%E9%87%8D%E6%96%B0%E6%A3%80%E6%9F%A5%E8%B0%93%E8%AF%8D%22%5D%0A%20%20M3%20--%3E%20M4%5B%22%E6%9D%A1%E4%BB%B6%E5%8F%AF%E8%83%BD%E5%8F%88%E6%B2%A1%E4%BA%86%3A%20%E5%BF%85%E9%A1%BB%E7%94%A8%20while%20%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">惊群就是一次唤醒把整条等待队列上的人都叫起来，结果只有一个人真正拿到活干，其余人白白消耗了一次加锁-检查-再睡的往返。广播语义正确但昂贵，能指名单个等待者时就用 signal。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Java <code>synchronized</code> 与 <code>Lock</code> 的全部 API 对照完，不引入无锁 condvar。Hoare 立即切换在当代运行时少见，读论文时不要默认 Linux 是 Hoare。死锁仍可能：两个管程各等对方，四个条件下一课才列。</p><p>嵌套管程调用会重入锁或死锁，语言实现必须规定；教学默认过程不跨越两个管程持锁。</p><p><span class="marginnote">初学者容易以为进了管程就进了保险箱、不会再死锁。实际上两个管程各持自己的锁再等对方的条件变量时，四个 Coffman 条件照样成立——管程消灭的是「忘记放锁」这类协议错误，不是循环等待本身。</span></p><p>后课默认：共享对象可用管程括号；<code>wait</code> 写在循环里（Mesa）。同步原语互等导致永久阻塞，下一课用 Coffman 条件刻画。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管程 = 数据 + 互斥过程；条件变量只是等待队列。</li><li>Mesa：唤醒后重新检查谓词。</li><li>跨对象互等仍可死锁。</li><li>出处：Hoare, <em>CACM</em> 1974；Lampson and Redell, Mesa, 1980（Mesa 语义）。</li></ul>',8))])}const g=l(c,[["render",p]]);export{_ as __pageData,g as default};
